namespace {
std::uint32_t PngCrc32(std::span<const std::uint8_t> bytes){std::uint32_t crc=0xffffffffu;for(const auto value:bytes){crc^=value;for(unsigned bit=0;bit<8;++bit)crc=(crc>>1)^((crc&1)?0xedb88320u:0);}return crc^0xffffffffu;}
void AppendBigEndian(std::vector<std::uint8_t>& output,std::uint32_t value){output.push_back(std::uint8_t(value>>24));output.push_back(std::uint8_t(value>>16));output.push_back(std::uint8_t(value>>8));output.push_back(std::uint8_t(value));}
bool InsertTextMetadata(const std::filesystem::path& source,const std::filesystem::path& target){std::ifstream input(source,std::ios::binary);std::vector<std::uint8_t> png((std::istreambuf_iterator<char>(input)),{});if(png.size()<12)return false;constexpr std::array<std::uint8_t,4> iend{'I','E','N','D'};const auto iendOffset=png.size()-8;if(!std::ranges::equal(std::span(png).subspan(iendOffset,4),iend))return false;const std::array<std::uint8_t,14> chunkData{'C','a','p','t','u','r','e',0,'p','i','n','n','e','d'};std::vector<std::uint8_t> chunk;AppendBigEndian(chunk,std::uint32_t(chunkData.size()));chunk.insert(chunk.end(),{'t','E','X','t'});chunk.insert(chunk.end(),chunkData.begin(),chunkData.end());AppendBigEndian(chunk,PngCrc32(std::span(chunk).subspan(4)));png.insert(png.begin()+std::ptrdiff_t(png.size()-12),chunk.begin(),chunk.end());std::ofstream output(target,std::ios::binary|std::ios::trunc);output.write(reinterpret_cast<const char*>(png.data()),std::streamsize(png.size()));return bool(output);}
bool DecodePngRgba(const std::filesystem::path& path,std::vector<std::uint8_t>& pixels){const HRESULT apartment=CoInitializeEx(nullptr,COINIT_MULTITHREADED);ComPtr<IWICImagingFactory> factory;ComPtr<IWICBitmapDecoder> decoder;ComPtr<IWICBitmapFrameDecode> frame;ComPtr<IWICFormatConverter> converter;UINT width{},height{};const bool initialized=SUCCEEDED(CoCreateInstance(CLSID_WICImagingFactory,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&factory)))&&SUCCEEDED(factory->CreateDecoderFromFilename(path.c_str(),nullptr,GENERIC_READ,WICDecodeMetadataCacheOnLoad,&decoder))&&SUCCEEDED(decoder->GetFrame(0,&frame))&&SUCCEEDED(frame->GetSize(&width,&height))&&width&&height&&SUCCEEDED(factory->CreateFormatConverter(&converter))&&SUCCEEDED(converter->Initialize(frame.Get(),GUID_WICPixelFormat32bppRGBA,WICBitmapDitherTypeNone,nullptr,0,WICBitmapPaletteTypeCustom));if(initialized){pixels.resize(std::size_t(width)*height*4);if(FAILED(converter->CopyPixels(nullptr,width*4,UINT(pixels.size()),pixels.data())))pixels.clear();}converter.Reset();frame.Reset();decoder.Reset();factory.Reset();if(apartment==S_OK||apartment==S_FALSE)CoUninitialize();return initialized&&!pixels.empty();}
}

int main(){
    const std::filesystem::path root=std::filesystem::temp_directory_path()/"Aevrynd"/"FrameCapture3DTest",output=root/"capture.png",invalid=root/"invalid.png";std::error_code error;std::filesystem::remove_all(root,error);const std::array<std::uint8_t,32> pixels={0,0,255,255,0,255,0,255,99,99,99,99,99,99,99,99,255,0,0,255,255,255,255,255,88,88,88,88,88,88,88,88};
    const FrameCaptureAnalysis3D analysis=AnalyzeFrameCaptureRgba8(2,2,16,pixels);if(!analysis.valid||analysis.sampledPixels!=4||analysis.averageLuminance<.49||analysis.averageLuminance>.51||analysis.darkPixelFraction!=0||analysis.brightPixelFraction<.24||analysis.brightPixelFraction>.26||analysis.linearAverageLuminance<.49||analysis.linearAverageLuminance>.51||analysis.linearLuminanceP05<.06||analysis.linearLuminanceP05>.08||analysis.linearLuminanceP50<.20||analysis.linearLuminanceP50>.22||analysis.linearLuminanceP95!=1||analysis.linearLuminanceP99!=1){std::cerr<<"Frame exposure analysis failed\n";return 5;}if(AnalyzeFrameCaptureRgba8(2,2,7,pixels).valid){std::cerr<<"Invalid frame analysis input was accepted\n";return 6;}
    PublishedFrameCapture3D publication{};if(!EncodeFrameCapturePng3D(output,2,2,16,pixels,publication)||!publication.Complete()||!ValidatePublishedFrameCapture3D(output,publication)||!std::filesystem::is_regular_file(output)){std::cerr<<"PNG frame capture publication failed\n";return 1;}std::ifstream file(output,std::ios::binary);std::array<unsigned char,8> signature{};file.read(reinterpret_cast<char*>(signature.data()),signature.size());const std::array<unsigned char,8> expected={137,80,78,71,13,10,26,10};if(signature!=expected){std::cerr<<"PNG signature failed\n";return 2;}
    const HRESULT apartment=CoInitializeEx(nullptr,COINIT_MULTITHREADED);ComPtr<IWICImagingFactory> factory;ComPtr<IWICBitmapDecoder> decoder;ComPtr<IWICBitmapFrameDecode> frame;ComPtr<IWICFormatConverter> converter;UINT width{},height{};std::array<std::uint8_t,16> decodedPixels{};const bool decoded=SUCCEEDED(CoCreateInstance(CLSID_WICImagingFactory,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&factory)))&&SUCCEEDED(factory->CreateDecoderFromFilename(output.c_str(),nullptr,GENERIC_READ,WICDecodeMetadataCacheOnLoad,&decoder))&&SUCCEEDED(decoder->GetFrame(0,&frame))&&SUCCEEDED(frame->GetSize(&width,&height))&&SUCCEEDED(factory->CreateFormatConverter(&converter))&&SUCCEEDED(converter->Initialize(frame.Get(),GUID_WICPixelFormat32bppRGBA,WICBitmapDitherTypeNone,nullptr,0,WICBitmapPaletteTypeCustom))&&SUCCEEDED(converter->CopyPixels(nullptr,8,UINT(decodedPixels.size()),decodedPixels.data()));converter.Reset();frame.Reset();decoder.Reset();factory.Reset();if(apartment==S_OK||apartment==S_FALSE)CoUninitialize();if(!decoded||width!=2||height!=2||decodedPixels[0]!=0||decodedPixels[1]!=0||decodedPixels[2]!=255||decodedPixels[4]!=0||decodedPixels[5]!=255||decodedPixels[6]!=0){std::cerr<<"PNG decode validation failed\n";return 3;}
    if(EncodeFrameCapturePng3D(invalid,2,2,7,pixels)||std::filesystem::exists(invalid)){std::cerr<<"Invalid row pitch was accepted\n";return 4;}
    const auto metadataOutput=root/"capture-metadata.png";if(!InsertTextMetadata(output,metadataOutput)){std::cerr<<"PNG metadata variant creation failed\n";return 7;}std::vector<std::uint8_t> metadataPixels;std::array<std::byte,32> pixelShaA{},pixelShaB{},fileShaA{},fileShaB{};if(!DecodePngRgba(metadataOutput,metadataPixels)||metadataPixels.size()!=decodedPixels.size()||!WorldDeltaSha2563D(std::as_bytes(std::span(decodedPixels)),pixelShaA)||!WorldDeltaSha2563D(std::as_bytes(std::span(metadataPixels)),pixelShaB)){return 8;}std::ifstream originalInput(output,std::ios::binary),metadataInput(metadataOutput,std::ios::binary);std::vector<char> originalBytes((std::istreambuf_iterator<char>(originalInput)),{}),metadataBytes((std::istreambuf_iterator<char>(metadataInput)),{});if(!WorldDeltaSha2563D(std::as_bytes(std::span(originalBytes)),fileShaA)||!WorldDeltaSha2563D(std::as_bytes(std::span(metadataBytes)),fileShaB)||pixelShaA!=pixelShaB||fileShaA==fileShaB){std::cerr<<"PNG pixel/file SHA separation failed\n";return 9;}
    std::filesystem::copy_file(metadataOutput,output,std::filesystem::copy_options::overwrite_existing,error);if(error||ValidatePublishedFrameCapture3D(output,publication)){std::cerr<<"Published PNG replacement was accepted\n";return 10;}std::cout<<"captureBytes="<<publication.finalFileBytes<<" width="<<width<<" height="<<height<<'\n';std::filesystem::remove_all(root,error);return 0;
}
